with flagged as (select *, case when lag(event_time) over (partition by page order by event_time, id) is null or event_time > lag(event_time) over (partition by page order by event_time, id) + interval '30' day then 1 else 0 end as is_new_session from web_events) select id, session_id, event_type, page, event_time, sum(is_new_session) over (partition by page order by event_time, id rows between unbounded preceding and current row) as burst_id from flagged
